#!/usr/bin/env bash
# Suite: hooks/generate-codex-agents.sh (.agents/agents/*.md -> .codex/agents/<codex-name>.toml, hyphens mapped to _; D9, D67).
# Covers: one toml per real definition with exactly name/description/developer_instructions and never `model` (D67), round-trip of
#   the values through a TOML parser (yq -p toml), determinism and --check drift detection, the basic-string fallback for bodies
#   containing ''', the [a-z0-9_] Codex name (fact-lookup -> fact_lookup) for file and key, pruning of stale generated files (including
#   the old hyphenated names) while user files are kept, and input rejections that write nothing (including a name collision).
# shellcheck disable=SC2016  # check expressions are single-quoted and eval'd on purpose
# shellcheck source=../lib/common.sh
source "$(dirname "${BASH_SOURCE[0]}")/../lib/common.sh"
preflight

new_workdir
P=$WORK/proj
copy_agents "$P"
G=$P/.agents/hooks/generate-codex-agents.sh
OUT=$P/.codex/agents

body_of() { # md file -> the body the generator should emit (after frontmatter, leading blank lines dropped, trailing ws trimmed) + "\n"
  local b
  b=$(awk 'NR == 1 { next } !d && /^---[[:space:]]*$/ { d = 1; next } d { print }' "$1" | awk 's || NF { s = 1; print }')
  b=${b%"${b##*[![:space:]]}"}
  printf '%s\n' "$b"
}

echo "== real definitions"
t "default run (project = parent of .agents)" 0 "$G"
n_src=$(find "$P/.agents/agents" -maxdepth 1 -name '*.md' | wc -l | tr -d ' ')
n_out=$(find "$OUT" -maxdepth 1 -name '*.toml' | wc -l | tr -d ' ')
eq "one toml per definition" "$n_out" "$n_src"
bad=""
for md in "$P"/.agents/agents/*.md; do
  n=$(basename "$md" .md)
  n=${n//-/_}
  f=$OUT/$n.toml
  j=$(yq -p toml -o json -I=0 '.' "$f" 2>/dev/null) || { bad="$bad $n:parse"; continue; }
  [ "$(jq -c 'keys' <<<"$j")" = '["description","developer_instructions","name"]' ] || bad="$bad $n:keys"
  [ "$(jq -r .name <<<"$j")" = "$n" ] || bad="$bad $n:name"
  [ "$(jq -r .description <<<"$j")" = "$(yq --front-matter=extract '.description' "$md")" ] || bad="$bad $n:description"
  [ "$(jq -j .developer_instructions <<<"$j")" = "$(body_of "$md")" ] || bad="$bad $n:body"
  head -n 1 "$f" | grep -q '^# Generated by .agents/hooks/generate-codex-agents.sh' || bad="$bad $n:marker"
done
eq "every toml parses, has exactly 3 keys, values round-trip" "$bad" ""
check "Codex names: only [a-z0-9_] in file names and name keys" \
  '! ls "$OUT" | grep -v "^[a-z0-9_]*\\.toml\$" && ! grep -h "^name = " "$OUT"/*.toml | grep -v "^name = \"[a-z0-9_]*\"\$"'
check "fact-lookup.md -> fact_lookup.toml with name fact_lookup, marker names the source" \
  'grep -qx "name = \"fact_lookup\"" "$OUT/fact_lookup.toml" && head -n 1 "$OUT/fact_lookup.toml" | grep -q "agents/fact-lookup.md"'
check "no toml carries a model key (D67)" '! grep -Eq "^[[:space:]]*model[[:space:]]*=" "$OUT"/*.toml'

sums() { (cd "$OUT" && cksum ./*.toml); }
before=$(sums)
t "second run" 0 "$G"
eq "deterministic: byte-identical output" "$(sums)" "$before"
t "--check clean" 0 "$G" --check
echo "# tampered" >> "$OUT/retrieval.toml"
t "--check detects a changed file" 1 "$G" --check
check "--check wrote nothing" 'tail -n 1 "$OUT/retrieval.toml" | grep -q tampered'
"$G"
eq "regeneration restores the file" "$(sums)" "$before"

echo "== fixture definitions"
A=$WORK/agents
O=$WORK/out
mkdir -p "$A"
cat > "$A/alpha.md" <<'M'
---
name: alpha
description: "Alpha agent: says \"hi\"."
tools: Read, Bash
model: opus
models: {claude: opus, codex: gpt-6-sol}
---


Line with a backslash \n and a 'quote'.
Tab	here.

M
cat > "$A/beta.md" <<'M'
---
name: beta
description: Beta.
---
Body with a triple quote ''' inside.
M
t "fixture run" 0 "$G" --agents-dir "$A" --out-dir "$O"
ja=$(yq -p toml -o json -I=0 '.' "$O/alpha.toml")
eq "alpha: model/models/tools dropped" "$(jq -c 'keys' <<<"$ja")" '["description","developer_instructions","name"]'
eq "alpha: description with quotes" "$(jq -r .description <<<"$ja")" 'Alpha agent: says "hi".'
eq "alpha: body verbatim, blank lines trimmed" "$(jq -j .developer_instructions <<<"$ja")" "$(printf 'Line with a backslash \\n and a '"'"'quote'"'"'.\nTab\there.\n')"
check "alpha: literal multi-line string" 'grep -q "^developer_instructions = '"'''"'\$" "$O/alpha.toml"'
jb=$(yq -p toml -o json -I=0 '.' "$O/beta.toml")
eq "beta: ''' body round-trips through the basic-string fallback" "$(jq -j .developer_instructions <<<"$jb")" "Body with a triple quote ''' inside."
nl=$(jq -rn --argjson a "$ja" --argjson b "$jb" '[$a, $b] | map(.developer_instructions | test("[^\\n]\\n$")) | all')
eq "both string forms end the value with exactly one newline" "$nl" true
check "beta: basic string used" 'grep -q "^developer_instructions = \"" "$O/beta.toml"'

echo "== pruning"
cp "$O/beta.toml" "$O/gone.toml"
printf 'name = "mine"\ndescription = "user agent"\ndeveloper_instructions = "x"\n' > "$O/mine.toml"
t "--check reports a stale generated file" 1 "$G" --agents-dir "$A" --out-dir "$O" --check
t "run prunes" 0 "$G" --agents-dir "$A" --out-dir "$O"
check "stale generated file removed" '[ ! -f "$O/gone.toml" ]'
check "user-written toml kept" '[ -f "$O/mine.toml" ]'

sed 's/^name = .*/name = "fact-lookup"/' "$OUT/fact_lookup.toml" > "$OUT/fact-lookup.toml"
t "--check reports an old hyphenated generated file" 1 "$G" --check
t "regeneration" 0 "$G"
check "old hyphenated generated file pruned" '[ ! -f "$OUT/fact-lookup.toml" ] && [ -f "$OUT/fact_lookup.toml" ]'

echo "== rejections (nothing written)"
reject() { # name file-content
  local d=$WORK/rej.$RANDOM o
  mkdir -p "$d/a"
  o=$d/out
  cp "$A/alpha.md" "$d/a/alpha.md"
  printf '%s' "$2" > "$d/a/zz.md"
  t "$1 -> exit 2" 2 "$G" --agents-dir "$d/a" --out-dir "$o"
  check "$1 -> no output dir" '[ ! -e "$o" ]'
}
reject "name mismatch" $'---\nname: other\ndescription: d\n---\nbody\n'
reject "missing description" $'---\nname: zz\n---\nbody\n'
reject "non-string name" $'---\nname: [zz]\ndescription: d\n---\nbody\n'
reject "empty body" $'---\nname: zz\ndescription: d\n---\n\n   \n'
reject "no frontmatter" $'just text\n'
reject "uppercase name" $'---\nname: ZZ\ndescription: d\n---\nbody\n'
C=$WORK/col
mkdir -p "$C/a"
printf -- '---\nname: a-b\ndescription: d\n---\nbody\n' > "$C/a/a-b.md"
printf -- '---\nname: a_b\ndescription: d\n---\nbody\n' > "$C/a/a_b.md"
t "a-b.md and a_b.md collide as a_b -> exit 2" 2 "$G" --agents-dir "$C/a" --out-dir "$C/out"
check "collision -> no output dir" '[ ! -e "$C/out" ]'
mkdir -p "$WORK/empty"
t "no definitions -> exit 2" 2 "$G" --agents-dir "$WORK/empty" --out-dir "$WORK/eo"
t "unknown flag -> exit 2" 2 "$G" --bogus

shellcheck_files "shellcheck: generate-codex-agents.sh" "$G"
finish
